#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll n, m;
vector<ll> a, vis;
vector<pair<ll, ll>> dp;

pair<ll, ll> rec(ll i) {
    if(i == 0) return {0, 0};
    if(vis[i]) return dp[i];
    vis[i] = 1;
    ll nv, mxv = -4e18, mxc = -1;
    if(i >= 1) {
        auto [v, c] = rec(i - 1);
        if(v != -4e18) {
            nv = v + a[i] * 6 - m;
            if(nv > mxv || (nv == mxv && c + 1 > mxc)) {
                mxv = nv;
                mxc = c + 1;
            }
        }
    }
    if(i >= 2) {
        auto [v, c] = rec(i - 2);
        if(v != -4e18) {
            nv = v + (a[i-1] + a[i]) * 4 - m;
            if(nv > mxv || (mxv == v && c + 1 > mxc)) {
                mxv = nv;
                mxc = c + 1;
            }
        }
    }
    if(i >= 3) {
        auto [v, c] = rec(i - 3);
        if(v != -4e18) {
            nv = v + (a[i-2] + a[i - 1] + a[i]) * 3 - m;
            if(nv > mxv || (mxv == nv && c + 1 > mxc)) {
                mxv = nv;
                mxc = c + 1;
            }
        }
    }
    return dp[i] = {mxv, mxc};
}

int main() {
    ll t;
    cin >> t;
    while(t--) {
        cin >> n;
        a.assign(n * 3 + 1, 0);
        for(ll i = 1; i <= n * 3; i++) cin >> a[i];
        sort(a.begin() + 1, a.end(), greater<ll>());
        
        ll l = 0, r = 2e10, ans = 0;
        while(l <= r) {
            m = l + (r - l)/2;
            dp.assign(n * 3 + 1, {-4e18, -1});
            vis.assign(n * 3 + 1, 0);
            
            ll mxd = -4e18, mxc = -1;
            for(ll i = 0; i <= n * 3; i++) {
                auto [v, c] = rec(i);
                if(v > mxd || (v == mxd && c > mxc)) {
                    mxd = v, mxc = c;
                }
            }
            
            if(mxc >= n) {
                ans = mxd + n * m;
                l = m + 1;
            } else {
                r = m - 1;
            }
        }
        cout<<ans<<"\n";
    }
}
